<?php require '_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$rid=(int)($_POST['rid']??0);$place=max(1,(int)($_POST['place']??1));$kills=max(0,(int)($_POST['kills']??0));$pp=[1=>10,2=>6,3=>5,4=>4,5=>3,6=>2,7=>1,8=>1][$place]??0;$s=$pdo->prepare("SELECT tournament_id,team_name FROM registrations WHERE registration_id=? AND status='confirmed'");$s->execute([$rid]);$r=$s->fetch();if($r){$s=$pdo->prepare("INSERT INTO scores(tournament_id,registration_id,team_name,placement,elimination_points,placement_points,total_points) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE placement=VALUES(placement),elimination_points=VALUES(elimination_points),placement_points=VALUES(placement_points),total_points=VALUES(total_points)");$s->execute([$r['tournament_id'],$rid,$r['team_name'],$place,$kills,$pp,$pp+$kills]);flash('success','Score saved. Total points: '.($pp+$kills));}else flash('danger','Only confirmed entries can be scored.');go('scores.php');}$entries=$pdo->query("SELECT r.registration_id,r.registration_code,r.team_name,t.name tn FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id WHERE r.status='confirmed' ORDER BY t.tournament_date DESC")->fetchAll();$rows=$pdo->query("SELECT s.*,t.name tn FROM scores s JOIN tournaments t ON t.tournament_id=s.tournament_id ORDER BY s.total_points DESC")->fetchAll();$pageTitle='Match scoring';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">ADMIN / RESULTS DESK</div><h1>MAKE EVERY <span>POINT COUNT.</span></h1><p>Placement points plus elimination points are calculated automatically.</p></section><?php require 'nav.php';?><div class="form-layout section"><section class="box"><div class="eyebrow">RESULT ENTRY</div><h2>Record team score</h2><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Confirmed team<select name="rid" required><?php foreach($entries as $r):?><option value="<?=(int)$r['registration_id']?>"><?=e($r['tn'].' — '.$r['team_name'].' ('.$r['registration_code'].')')?></option><?php endforeach;?></select></label><label>Placement<input type="number" min="1" name="place" value="1" required></label><label>Eliminations<input type="number" min="0" name="kills" value="0" required></label><div class="notice">Demo scoring: 1st 10, 2nd 6, 3rd 5, 4th 4, 5th 3, 6th 2, 7th–8th 1, plus one point per elimination. Change to match event rules.</div><button class="btn btn-hot">Save score ↗</button></form></section><section class="box"><div class="eyebrow">CURRENT STANDINGS</div><h2>Latest scores</h2><?php foreach($rows as $r):?><div class="list-row"><div><b><?=e($r['team_name'])?> · <?=$r['total_points']?> pts</b><small><?=e($r['tn'])?> · Placement #<?=$r['placement']?> · Eliminations <?=$r['elimination_points']?></small></div></div><?php endforeach;?></section></div><?php require '../includes/footer.php';?>
